import { TRACK_NODE_DISTANCES } from "./trackNodeDistances.js";

/** @type {Map<string, { key: string, dist: number, prev_node: string, next_node: string }>} */
const trackByToken = new Map(
  Object.entries(TRACK_NODE_DISTANCES).map(([key, edge]) => [
    key.toLowerCase(),
    { key, ...edge },
  ])
);

const MAX_EDGE_WALK = 64;

export function normalizeTrackToken(token) {
  return token.trim().toLowerCase();
}

export function getEdgeInfo(nodeToken) {
  return trackByToken.get(normalizeTrackToken(nodeToken)) ?? null;
}

/**
 * Walk along track edges until `mm` lies on the current edge (0 … dist).
 * Negative mm extends into prev_node edges; mm > dist extends into next_node.
 */
export function resolveEdgePosition(nodeToken, mm) {
  let key = normalizeTrackToken(nodeToken);
  let position = mm;

  for (let step = 0; step < MAX_EDGE_WALK; step += 1) {
    const edge = trackByToken.get(key);
    if (!edge) {
      return null;
    }

    if (edge.dist <= 0) {
      return { key: edge.key, mm: 0 };
    }

    if (position >= 0 && position <= edge.dist) {
      return { key: edge.key, mm: position };
    }

    if (position < 0) {
      key = normalizeTrackToken(edge.prev_node);
      const prevEdge = trackByToken.get(key);
      if (!prevEdge) {
        return null;
      }
      position = prevEdge.dist + position;
      continue;
    }

    key = normalizeTrackToken(edge.next_node);
    position -= edge.dist;
  }

  return null;
}

/**
 * Map mm along a directed track edge to a fraction on an SVG path segment.
 * SVG labels list endpoint tokens; track edges run prev_node → next_node.
 */
export function mmToFraction(tokens, nodeKey, mm) {
  const edge = getEdgeInfo(nodeKey);
  if (!edge || edge.dist <= 0 || tokens.length === 0) {
    return null;
  }

  const prev = normalizeTrackToken(edge.prev_node);
  const next = normalizeTrackToken(edge.next_node);
  const key = normalizeTrackToken(nodeKey);
  const start = tokens[0];
  const end = tokens[tokens.length - 1];
  const ratio = Math.max(0, Math.min(1, mm / edge.dist));

  if (start === prev && end === next) {
    return ratio;
  }
  if (start === next && end === prev) {
    return 1 - ratio;
  }
  if (start === key && end === prev) {
    return 1 - ratio;
  }
  if (start === key && end === next) {
    return ratio;
  }
  if (start === prev && end === key) {
    return ratio;
  }
  if (start === next && end === key) {
    return 1 - ratio;
  }

  if (tokens.includes(key)) {
    if (end === prev || start === next) {
      return 1 - ratio;
    }
    if (start === prev || end === next) {
      return ratio;
    }
  }

  return null;
}
